-- ── story 4-2b: cancel a picked or packed order — the voided label ─────────
-- Generated by drizzle-kit (the two column statements) and hand-amended
-- around the generated part: the fail-fast guard, the two CHECKs and the
-- post-migration probe (drizzle-kit is blind to CHECKs; `bun run db:generate`
-- afterwards reports "No schema changes").
--
-- `shipments` gains the `voided` arm: the label of an order cancelled with
-- restock before it was manifested (`CancelRestockCommandService`,
-- src/modules/outbound/cancel-restock.command.ts). The void is LOCAL — the
-- only label-producing carrier is the sandbox, so no AWB exists at a real
-- courier (each transport story adds its AWB-cancel arm, PENDING carriers).
--   * `voided_at timestamptz NULL`, `voided_by uuid NULL` — set together with
--     `status = 'voided'`, never otherwise (`shipments_voided_pairing`).
--   * `shipments_status_check` is DROPPED and re-ADDED with the third arm
--     (guide §3/§4 — widening a CHECK is drop then add, the 0023/0024
--     precedent). Mirrored by `SHIPMENT_STATUSES`
--     (src/modules/outbound/shipment.command.ts), pinned TS ↔ DB by
--     test/label.spec.ts.
--
-- Both CHECKs are added NOT VALID (guide §3): `shipments` grows with every
-- label, and a VALID add would scan it under the ACCESS EXCLUSIVE lock.
-- NOT VALID is safe for both by construction:
--   * every existing row was validated under the NARROWER status set
--     (labelled, manifested), so it satisfies the wider one;
--   * every existing row reads NULL in both new columns and a non-voided
--     status, so `(status = 'voided') = (voided_at … AND voided_by …)` is
--     `false = false`.
-- No VALIDATE here — the migrator runs the pending set in ONE transaction,
-- so a VALIDATE would scan under the ADD's lock; it is a PENDING entry.
--
-- No backfill and no new lookup structure. The partial unique
-- `shipments_tenant_order_labelled_unique` (WHERE status = 'labelled') is
-- unchanged, so a voided row simply stops covering its order.
--
-- Lock cost: each ADD COLUMN and each constraint statement takes a brief
-- ACCESS EXCLUSIVE lock with no rewrite and no scan. The deploy migrator sets
-- `lock_timeout` (MIGRATE_LOCK_TIMEOUT_MS, default 5 s): a lock it cannot
-- take fails the deploy cleanly for a re-run (DEPLOY.md §5).

-- ── 0. fail-fast: already applied, or out of order ──────────────────────
DO $$
BEGIN
	IF EXISTS (
		SELECT 1 FROM information_schema.columns
		 WHERE table_schema = 'public' AND table_name = 'shipments' AND column_name = 'voided_at'
	) THEN
		RAISE EXCEPTION 'migration 0102: shipments.voided_at already exists — this migration has already been applied.';
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM information_schema.tables
		 WHERE table_schema = 'public' AND table_name = 'batch_recalls'
	) THEN
		RAISE EXCEPTION 'migration 0102 is out of order: batch_recalls does not exist — 0101 must be applied first.';
	END IF;
END $$;
--> statement-breakpoint
ALTER TABLE "shipments" ADD COLUMN "voided_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "shipments" ADD COLUMN "voided_by" uuid;--> statement-breakpoint
-- ── hand-amended: the CHECKs (migration SQL only), NOT VALID ─────────────
ALTER TABLE "shipments" DROP CONSTRAINT "shipments_status_check";--> statement-breakpoint
ALTER TABLE "shipments" ADD CONSTRAINT "shipments_status_check" CHECK (
	"status" IN ('labelled','manifested','voided')
) NOT VALID;--> statement-breakpoint
ALTER TABLE "shipments" ADD CONSTRAINT "shipments_voided_pairing" CHECK (
	("status" = 'voided') = ("voided_at" IS NOT NULL AND "voided_by" IS NOT NULL)
) NOT VALID;--> statement-breakpoint
-- ── the post-migration assertion (the 0093 model) ─────────────────────────
-- Made-up uuids. (a) Both CHECKs are present and NOT VALID. (b) The accepted
-- shapes — a voided row with both stamps, a labelled row without — are
-- inserted and rolled back by a sentinel exception, so a CHECK that refused
-- everything fails the migration. (c) Each refused shape runs in its own
-- subtransaction and must be refused BY ITS NAMED CONSTRAINT. Constraint
-- order (guide §3 — CHECKs run in name order): each refused probe violates
-- ONLY its target — `voided` without stamps and `labelled` with stamps break
-- the pairing alone (the status CHECK admits both arms, and with no
-- `manifest_id` `shipments_manifest_pairing` reads false = false); an unknown
-- status breaks the status CHECK alone (it is neither voided nor manifested).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	cc uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
	unvalidated int;
BEGIN
	-- (a) both present and NOT VALID.
	SELECT count(*) INTO unvalidated
	  FROM pg_constraint
	 WHERE conrelid = 'public.shipments'::regclass
	   AND conname IN ('shipments_status_check', 'shipments_voided_pairing')
	   AND contype = 'c'
	   AND NOT convalidated;
	IF unvalidated <> 2 THEN
		RAISE EXCEPTION 'migration 0102: expected shipments_status_check and shipments_voided_pairing present and NOT VALID, found % so.', unvalidated;
	END IF;
	-- (b) the accepted shapes.
	BEGIN
		INSERT INTO "shipments" ("id","tenant_id","warehouse_id","order_id","status","carrier_connection_id","carrier_code","carrier_name","tracking_number","label_document_ref","labelled_by","labelled_at","voided_at","voided_by")
		VALUES
			(gen_random_uuid(), t, w, gen_random_uuid(), 'voided', cc, 'sandbox', 'Sandbox', 'SBX-PROBE-1', 'sandbox://probe/1', u, now(), now(), u),
			(gen_random_uuid(), t, w, gen_random_uuid(), 'labelled', cc, 'sandbox', 'Sandbox', 'SBX-PROBE-2', 'sandbox://probe/2', u, now(), NULL, NULL);
		RAISE EXCEPTION USING ERRCODE = 'P0102', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0102: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0102' THEN
			NULL;
	END;
	-- (c) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY['voided without stamps', 'voided half stamped', 'labelled with stamps', 'unknown status'] LOOP
		refused_by := NULL;
		expected := CASE
			WHEN probe = 'unknown status' THEN 'shipments_status_check'
			ELSE 'shipments_voided_pairing'
		END;
		BEGIN
			INSERT INTO "shipments" ("id","tenant_id","warehouse_id","order_id","status","carrier_connection_id","carrier_code","carrier_name","tracking_number","label_document_ref","labelled_by","labelled_at","voided_at","voided_by")
			VALUES (
				gen_random_uuid(), t, w, gen_random_uuid(),
				CASE probe WHEN 'labelled with stamps' THEN 'labelled' WHEN 'unknown status' THEN 'lost' ELSE 'voided' END,
				cc, 'sandbox', 'Sandbox', 'SBX-PROBE-R', 'sandbox://probe/r', u, now(),
				CASE probe WHEN 'voided without stamps' THEN NULL WHEN 'unknown status' THEN NULL ELSE now() END,
				CASE probe WHEN 'labelled with stamps' THEN u ELSE NULL END
			);
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0102: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "shipments" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0102: a probe row survived.';
	END IF;
END $$;
